CREATE TABLE IF NOT EXISTS tasks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,assigned_user_id UUID REFERENCES users(id) ON DELETE SET NULL,lead_id UUID REFERENCES leads(id) ON DELETE SET NULL,opportunity_id UUID REFERENCES opportunities(id) ON DELETE SET NULL,title TEXT NOT NULL,description TEXT,status TEXT NOT NULL DEFAULT 'open',priority TEXT NOT NULL DEFAULT 'normal',due_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);CREATE INDEX IF NOT EXISTS tasks_tenant_idx ON tasks(tenant_id,status,due_at);